procedure ClinicConfirmNewAppointment {
  about "Confirm a new appointment and add it to the calendar"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  calendar Rooms "Rooms"
  trigger when new row r in Visits

  if r.starts < now() + 12 hours {
    notify owner "Short-notice appointment for {r.patient} at {r.starts}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.patient default 'there'}, your appointment with the clinic is confirmed for {r.starts}."
  let ok = request approval of m from owner timeout 2 hours else stop "confirmation not approved"
  send ok
  let ev = book Rooms { title: "{r.patient}", at: r.starts, length: 45 minutes }
  update r set status = "confirmed"
}

