policy PrintshopStockPolicy {
  allow read Paper(stock_name, reams, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Paper.supplier
  limit order $200 per action
  limit order $800 per day
}

program:
procedure PrintshopReorder {
  about "Reorder paper below their minimum"
  policy PrintshopStockPolicy
  sheet Paper "Paper" { stock_name: Text, reams: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every monday at 16:00

  let all = fetch Paper
  let low = filter all where reams < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.stock_name} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.stock_name}" from i.supplier cost cost, ask owner first timeout 6 hours else skip
    log "ordered {i.stock_name}"
  }
}

